import{ad as u,N as p,$ as m,Q as n,j as s,g as t,o as f,n as i,a4 as l,a9 as g,m as y,i as b,X as v}from"./chunks/framework.Ce_49mA8.js";const w={id:"license-agreement-privacy-policy",tabindex:"-1"},P=["href"],L=JSON.parse('{"title":"License & Privacy Policy","description":"End-User License Agreement (EULA), Privacy Policy, and Payment Terms for OmniCraft ERP.","frontmatter":{"title":"License & Privacy Policy","description":"End-User License Agreement (EULA), Privacy Policy, and Payment Terms for OmniCraft ERP.","order":20,"eula_version":20261120,"eula_date":"2026-11-20","datePublished":"2026-11-14","dateModified":"2026-11-20"},"headers":[],"relativePath":"docs/terms.md","filePath":"docs/terms.md","lastUpdated":1795132800000}'),T={name:"docs/terms.md"},U=Object.assign(T,{setup(q){const{frontmatter:c}=u(),a=v("");p(()=>{a.value="nm@omnicraft-erp.com"});const d=r=>{if(!r)return"";const[e,o,h]=r.split("-");return`${["January","February","March","April","May","June","July","August","September","October","November","December"][parseInt(o)-1]} ${parseInt(h)}, ${e}`};return(r,e)=>{const o=m("DocIcon");return n(),s("div",null,[t("h1",w,[f(o,{name:"terms"}),e[0]||(e[0]=i(" License Agreement & Privacy Policy ",-1)),e[1]||(e[1]=t("a",{class:"header-anchor",href:"#license-agreement-privacy-policy","aria-label":'Permalink to "License Agreement & Privacy Policy"'},"​",-1))]),t("p",null,[t("em",null,"Effective Date: "+l(d(g(c).eula_date)),1)]),e[6]||(e[6]=y('<p>This document is an official offer (public agreement) and constitutes a single legal agreement between you (hereinafter — the &quot;User&quot;) and the Developer (hereinafter — the &quot;Licensor&quot;) regarding the use of the &quot;OmniCraft ERP&quot; software (hereinafter — the &quot;Software&quot;) and the official website.</p><p>By installing, copying, downloading, paying for, or otherwise using the Software, the User unconditionally agrees to all the terms of this document. If you do not agree to the terms, you must cease using the Software and delete it from your devices.</p><hr><h2 id="part-1-end-user-license-agreement-eula" tabindex="-1">PART 1. END-USER LICENSE AGREEMENT (EULA) <a class="header-anchor" href="#part-1-end-user-license-agreement-eula" aria-label="Permalink to &quot;PART 1. END-USER LICENSE AGREEMENT (EULA)&quot;">​</a></h2><h3 id="_1-1-subject-of-the-agreement-and-operating-principle" tabindex="-1">1.1. Subject of the Agreement and Operating Principle <a class="header-anchor" href="#_1-1-subject-of-the-agreement-and-operating-principle" aria-label="Permalink to &quot;1.1. Subject of the Agreement and Operating Principle&quot;">​</a></h3><p>The Licensor grants the User a personal, non-exclusive, non-transferable right to use the Software according to its functional purpose worldwide for the entire duration of the exclusive right.</p><p>The Software is developed based on an architecture with a priority on local data storage (Local-First). Data processing and record-keeping are carried out on the User&#39;s computing resources. The Licensor does not store the User&#39;s databases on its servers and has no access to them. All accounting and commercial information (databases, route sheets, financial records, customer records, inventory balances) is created, processed, and stored under the exclusive control of the User — on their local storage devices or in user-connected personal data storage.</p><h3 id="_1-2-license-types-and-tiers" tabindex="-1">1.2. License Types and Tiers <a class="header-anchor" href="#_1-2-license-types-and-tiers" aria-label="Permalink to &quot;1.2. License Types and Tiers&quot;">​</a></h3><p>The Licensor grants rights to use the Software to the extent of the functional capabilities determined by the license tier (subscription or perpetual plan) selected by the User.</p><p>The full list of active license tiers, available features, validity periods, trial access terms, and pricing is publicly available on the official <a href="/docs/buy-license">Purchasing a License</a> page and in the <a href="/docs/licenses">Licensing Guide</a>, which form an integral part of this Offer.</p><p>A commercial license key is technically bound to the unique hardware identifier (HWID) of the User&#39;s device and permits simultaneous activation on up to 5 (five) devices of the User, with the ability to independently reset and reassign bindings in the personal cabinet.</p><h3 id="_1-3-usage-restrictions" tabindex="-1">1.3. Usage Restrictions <a class="header-anchor" href="#_1-3-usage-restrictions" aria-label="Permalink to &quot;1.3. Usage Restrictions&quot;">​</a></h3><p>The User is strictly prohibited from:</p><ul><li>Decompiling, disassembling, modifying, or attempting to extract the source code of the Software.</li><li>Renting, selling, sublicensing, or transferring activation keys to third parties.</li><li>Using the Software for actions contrary to applicable law.</li><li>Attempting to bypass the technical limitations of the trial version by any means.</li></ul><h3 id="_1-4-limitation-of-liability-and-disclaimer-of-warranties" tabindex="-1">1.4. Limitation of Liability and Disclaimer of Warranties <a class="header-anchor" href="#_1-4-limitation-of-liability-and-disclaimer-of-warranties" aria-label="Permalink to &quot;1.4. Limitation of Liability and Disclaimer of Warranties&quot;">​</a></h3><p><strong>The Software is provided on an &quot;as is&quot; basis. The Licensor makes no express or implied warranties that the Software will meet the User&#39;s requirements, or that it will operate uninterrupted, without failures or errors.</strong></p><p><strong>The User understands and agrees that under no circumstances shall the Licensor be liable for:</strong></p><ol><li>Loss, distortion, or corruption of the User&#39;s databases resulting from power failures, storage hardware malfunction, malicious software, or improper actions by the User.</li><li>Any direct or indirect damages, lost profits, or business interruption arising from the use or inability to use the Software.</li></ol><p><strong>Backups:</strong> The User acknowledges that the entire responsibility for the safety of commercial information rests solely with them. The User agrees to independently and regularly back up their data using the Software&#39;s built-in tools to external storage media or personal storage repositories.</p><p><strong>Artificial Intelligence (AI) Integration and Data Processing:</strong> The Software provides capabilities for interacting with third-party artificial intelligence providers under a direct connection model with personal access keys, as well as with offline local models. The User acknowledges and unconditionally agrees to the following:</p><ol><li>When external cloud models are utilized, prompt texts and operational context (including material names, item specifications, generated descriptions, work order notes, and related details) are transmitted directly from the User&#39;s device to the servers of the chosen third-party AI provider using the User&#39;s personal access key. The Licensor has no access to these communication channels, and does not intercept, inspect, analyze, or store the contents of AI queries.</li><li>If the User inputs personal data of third parties (including clients, customers, contractors, or employees) or legally protected trade secrets into AI prompts, the User acts as an independent data controller and assumes sole and full responsibility for compliance with applicable data protection legislation (including GDPR, regional privacy laws, and cross-border transfer requirements, as well as obtaining all necessary data subject consents). The Licensor bears no responsibility for the processing practices or actions of third-party AI providers regarding data transmitted by the User.</li><li>The User has the technical option to eliminate external network transmission entirely by utilizing offline local AI models that execute strictly on the hardware resources of the User&#39;s local device without internet connectivity.</li><li>All information, calculations, text generations, and materials produced using AI technologies are provided strictly on an &quot;as is&quot; basis and serve informational and assistive purposes only. The User is obligated to independently validate and verify any operational, economic, and financial data prior to its final approval and real-world application.</li></ol><p><strong>Liability Cap:</strong> The Licensor&#39;s aggregate liability for any claims, demands, or lawsuits arising out of or related to this Agreement or the operation of the Software shall under all circumstances be strictly limited to proven direct actual damages and shall in no event exceed the amount actually paid by the User for the respective license. With respect to the free trial version of the Software, the Licensor bears no financial liability whatsoever. Under no circumstances shall the Licensor be liable for any lost profits, consequential damages, business interruption, or loss of the User&#39;s data.</p><h3 id="_1-5-payment-delivery-and-return-terms" tabindex="-1">1.5. Payment, Delivery, and Return Terms <a class="header-anchor" href="#_1-5-payment-delivery-and-return-terms" aria-label="Permalink to &quot;1.5. Payment, Delivery, and Return Terms&quot;">​</a></h3><p>The procedure for paying for license keys, delivery methods for the digital product, as well as the rules, deadlines, and comprehensive refund policy are detailed in <a href="#payment-delivery-returns">Part 3 of this Agreement</a>.</p><hr><h2 id="privacy-policy" tabindex="-1">PART 2. PRIVACY POLICY <a class="header-anchor" href="#privacy-policy" aria-label="Permalink to &quot;PART 2. PRIVACY POLICY {#privacy-policy}&quot;">​</a></h2><h3 id="_2-1-no-collection-of-user-project-data" tabindex="-1">2.1. No Collection of User Project Data <a class="header-anchor" href="#_2-1-no-collection-of-user-project-data" aria-label="Permalink to &quot;2.1. No Collection of User Project Data&quot;">​</a></h3><p>Due to the architecture prioritizing local data storage, the Licensor has no access to the User&#39;s databases. The Licensor does not collect, process, or store the personal data of the User&#39;s clients, supplier lists, trade secrets, income data, or account balances.</p><p>The Licensor does not act as a data controller or data processor with respect to information entered by the User into the Software&#39;s database.</p><h3 id="_2-2-automatically-collected-technical-information-telemetry" tabindex="-1">2.2. Automatically Collected Technical Information (Telemetry) <a class="header-anchor" href="#_2-2-automatically-collected-technical-information-telemetry" aria-label="Permalink to &quot;2.2. Automatically Collected Technical Information (Telemetry)&quot;">​</a></h3><p>To ensure the operation of the licensing system and improve the Software&#39;s quality, the Licensor may collect strictly anonymized technical telemetry:</p><ul><li><strong>Hardware ID (HWID):</strong> An anonymized cryptographic hash of hardware parameters used solely for verifying license binding and anti-piracy protection. This code does not allow the identification of an individual.</li><li><strong>Technical Metrics:</strong> Interface language, operating system version, Software version, and sales transaction counter (to verify trial limits).</li><li><strong>Crash Reports:</strong> In the event of a critical error, the Software generates an error log (traceback) where local PC directory paths are masked to avoid transmitting system account names.</li></ul><h3 id="_2-3-processing-of-data-during-checkout" tabindex="-1">2.3. Processing of Data During Checkout <a class="header-anchor" href="#_2-3-processing-of-data-during-checkout" aria-label="Permalink to &quot;2.3. Processing of Data During Checkout&quot;">​</a></h3><ul><li>Upon purchasing and paying for a license through an authorized payment gateway, the User provides an email address and device hardware ID.</li><li>By providing data, the User consents to the processing of this information by the Licensor solely for the purpose of automatic generation, delivery, and technical support of the license key.</li><li><strong>To ensure privacy and minimize data collection, the email address is used solely to dispatch the message with the license key immediately upon completion of the transaction and is not saved or stored in databases on the Licensor&#39;s servers.</strong> Only the anonymized license token and the device&#39;s hashed fingerprint are stored in the license database.</li><li>Data processing is carried out in compliance with applicable law. Data is not transferred to third parties (except for the lawful demands of authorized state authorities).</li></ul><h3 id="_2-4-consent-management-opt-out" tabindex="-1">2.4. Consent Management (Opt-Out) <a class="header-anchor" href="#_2-4-consent-management-opt-out" aria-label="Permalink to &quot;2.4. Consent Management (Opt-Out)&quot;">​</a></h3><p>The User has the right to withdraw consent to the transmission of analytical telemetry and crash reports at any time. To do so, simply uncheck the corresponding option in the <a href="./global-settings">Global Settings</a> section of the Software. Upon disabling this parameter, the Software switches to fully offline operation (with the exception of one-time requests to verify commercial license activation).</p><h3 id="_2-5-web-resources-usage" tabindex="-1">2.5. Web Resources Usage <a class="header-anchor" href="#_2-5-web-resources-usage" aria-label="Permalink to &quot;2.5. Web Resources Usage&quot;">​</a></h3><p>When visiting <code>omnicraft-erp.com</code> or interacting with the Licensor&#39;s official authorization servers, the web server may automatically log standard connection data (IP address, browser type, access time) solely for network security and DDoS mitigation. The website does not use advertising or tracking third-party cookies.</p><h3 id="_2-6-local-and-session-browser-storage" tabindex="-1">2.6. Local and Session Browser Storage <a class="header-anchor" href="#_2-6-local-and-session-browser-storage" aria-label="Permalink to &quot;2.6. Local and Session Browser Storage&quot;">​</a></h3><p>The website uses local session browser storage strictly to maintain the technical functionality of the user cabinet and preserve authorization status during an active user session. Data is stored locally on the user&#39;s device. Stored information is not used for tracking or marketing purposes and is automatically erased by the browser when the tab or browser window is closed.</p><hr><h2 id="payment-delivery-returns" tabindex="-1">PART 3. PAYMENT, DELIVERY &amp; RETURNS <a class="header-anchor" href="#payment-delivery-returns" aria-label="Permalink to &quot;PART 3. PAYMENT, DELIVERY &amp; RETURNS {#payment-delivery-returns}&quot;">​</a></h2><h3 id="_3-1-product-description-and-properties" tabindex="-1">3.1. Product Description and Properties <a class="header-anchor" href="#_3-1-product-description-and-properties" aria-label="Permalink to &quot;3.1. Product Description and Properties&quot;">​</a></h3><p>The product is a non-exclusive right to use the software (digital license activation key).</p><p>Product properties: activating the license key in OmniCraft ERP removes the basic technical restrictions of the free trial version and, depending on the selected plan, grants access to advanced features. The product is delivered exclusively in digital (electronic) form.</p><h3 id="_3-2-payment-conditions-and-methods" tabindex="-1">3.2. Payment Conditions and Methods <a class="header-anchor" href="#_3-2-payment-conditions-and-methods" aria-label="Permalink to &quot;3.2. Payment Conditions and Methods&quot;">​</a></h3><p>Payment is processed online in a cashless manner via an authorized payment gateway (online payment processing), which fully complies with payment card industry data security standards.</p><p>All transmitted payment details are encrypted using secure cryptographic protocols.</p><p>The actual list of available payment methods (bank cards, instant payment systems, and other electronic methods) is determined by the payment gateway at the time of transaction and displayed directly in the checkout payment form on the <a href="/docs/buy-license">Purchasing a License</a> page.</p><h3 id="_3-3-delivery-process" tabindex="-1">3.3. Delivery Process <a class="header-anchor" href="#_3-3-delivery-process" aria-label="Permalink to &quot;3.3. Delivery Process&quot;">​</a></h3><ul><li>Delivery of the digital product is carried out by sending an email with the license key to the email address provided by the Buyer during checkout.</li><li>Delivery timeline: the email with the license key is dispatched automatically immediately upon payment confirmation, but no later than 24 hours from the transaction.</li></ul><h3 id="_3-4-returns-and-order-cancellations" tabindex="-1">3.4. Returns and Order Cancellations <a class="header-anchor" href="#_3-4-returns-and-order-cancellations" aria-label="Permalink to &quot;3.4. Returns and Order Cancellations&quot;">​</a></h3><ul><li><p><strong>Cancellation before receiving the digital product:</strong><br> The Buyer has the right to cancel the purchase and receive a full refund at any time before the actual automatic generation and dispatch of the license key to their email address.</p></li><li><p><strong>Step-by-step refund procedure:</strong></p><ol><li>To request a refund, the User submits a free-form request via the <a href="/docs/contacts">Contacts &amp; Legal Details</a> page. The request must include the payment date, amount, and the email address specified during checkout.</li><li>The refund request is processed by the Licensor, and funds are returned within <strong>up to 10 (ten) calendar days</strong> from the receipt of the request in accordance with applicable consumer protection laws.</li><li>Upon approval, the refund is issued in full (<strong>100% of the paid amount without deducting processing commissions</strong>) to the same account or payment card from which the payment was made.</li><li>The actual arrival of funds to the User&#39;s account depends on the issuing bank and payment system rules (typically up to 30 calendar days).</li></ol></li><li><p><strong>Cancellation after receiving the digital license key:</strong><br> The provision of the non-exclusive right to the Software is deemed fully executed (service completely rendered) at the moment the unique license activation key is automatically generated and sent to the User&#39;s email address. In accordance with applicable software licensing regulations and digital consumer protection standards, refunds for a digital product of proper quality are not provided after its transmission to the User.</p><p>Prior to purchasing a commercial license, the User is provided with a free trial version of the Software without time limits to fully evaluate its features, compatibility, and consumer properties. In case of any technical issues with key activation, the Licensor commits to promptly resolving the issue or replacing the key.</p></li></ul><hr><h2 id="part-4-final-provisions-and-details" tabindex="-1">PART 4. FINAL PROVISIONS AND DETAILS <a class="header-anchor" href="#part-4-final-provisions-and-details" aria-label="Permalink to &quot;PART 4. FINAL PROVISIONS AND DETAILS&quot;">​</a></h2><h3 id="_4-1-applicable-law-and-dispute-resolution" tabindex="-1">4.1. Applicable Law and Dispute Resolution <a class="header-anchor" href="#_4-1-applicable-law-and-dispute-resolution" aria-label="Permalink to &quot;4.1. Applicable Law and Dispute Resolution&quot;">​</a></h3><p>This Agreement is governed by and construed in accordance with the laws of the Russian Federation. All disputes and disagreements arising in connection with this Agreement shall be subject to mandatory pre-trial claim settlement. The period for considering a written claim is 30 (thirty) calendar days from the date of its receipt. If a dispute cannot be resolved through the pre-trial procedure, it shall be referred to the court at the Licensor&#39;s location.</p><h3 id="_4-2-force-majeure" tabindex="-1">4.2. Force Majeure <a class="header-anchor" href="#_4-2-force-majeure" aria-label="Permalink to &quot;4.2. Force Majeure&quot;">​</a></h3><p>The Parties shall be released from liability for partial or complete failure to perform their obligations under this Agreement if such failure is caused by force majeure events. Such circumstances include extraordinary and unavoidable events, including military actions, natural disasters, decisions of government authorities, large-scale failures in the Internet, failures of servers or cloud providers, as well as severe sudden illness or emergency hospitalization of the Licensor that objectively prevents the performance of obligations in a timely manner.</p><h3 id="_4-3-amendments" tabindex="-1">4.3. Amendments <a class="header-anchor" href="#_4-3-amendments" aria-label="Permalink to &quot;4.3. Amendments&quot;">​</a></h3><p>The Licensor reserves the right to unilaterally amend this Agreement. The new version becomes effective from the moment it is published on the official website of the Program. In the event of the User&#39;s disagreement with the amendments to the Agreement, the User must immediately cease all use of the Program and delete it from their devices.</p><h3 id="_4-4-language-of-the-agreement" tabindex="-1">4.4. Language of the Agreement <a class="header-anchor" href="#_4-4-language-of-the-agreement" aria-label="Permalink to &quot;4.4. Language of the Agreement&quot;">​</a></h3><p>This Agreement may be translated into other languages for the convenience of Users. In the event of any discrepancies, contradictions, or inconsistencies between the Russian version of this Agreement and its version in any other language, the Russian version shall always prevail, govern, and be final.</p><h3 id="_4-5-developer-licensor-details" tabindex="-1">4.5. Developer (Licensor) Details <a class="header-anchor" href="#_4-5-developer-licensor-details" aria-label="Permalink to &quot;4.5. Developer (Licensor) Details&quot;">​</a></h3><p>The copyright holder and Developer of the Software is: <strong>Nikolai Valerievich Murashkin</strong>, registered as self-employed (NPD tax regime in the Russian Federation). Detailed information about the developer is available in the <a href="/docs/about">About the Developers</a> section.</p>',65)),t("ul",null,[e[5]||(e[5]=t("li",null,[t("strong",null,"Tax ID (INN):"),i(" 232904256501")],-1)),t("li",null,[e[2]||(e[2]=t("strong",null,"Official Email Address:",-1)),e[3]||(e[3]=i()),a.value?(n(),s("a",{key:0,href:"mailto:"+a.value,class:"eula-email"},l(a.value),9,P)):b("",!0),e[4]||(e[4]=i(" (for legally significant communications, notices, and pre-trial claims)",-1))])])])}}});export{L as __pageData,U as default};
